using namespace std;

struct Tok {
    string s;
    int pos = 0;
    void skipWS() { while(pos<(int)s.size()&&(s[pos]==' '||s[pos]==','||s[pos]=='\t'||s[pos]=='\n'||s[pos]=='\r')) pos++; }
    string nextToken() {
        skipWS();
        if(pos>=(int)s.size()) return "";
        if(s[pos]=='['){
            int depth=0,st=pos;
            while(pos<(int)s.size()){char c=s[pos++];if(c=='[')depth++;else if(c==']'){depth--;if(depth==0)break;}}
            return s.substr(st,pos-st);
        } else if(s[pos]=='"'){
            int st=pos++;
            while(pos<(int)s.size()&&s[pos]!='"')pos++;
            if(pos<(int)s.size()) pos++;
            return s.substr(st,pos-st);
        } else {
            int st=pos;
            while(pos<(int)s.size()&&s[pos]!=','&&s[pos]!=']'&&s[pos]!='[')pos++;
            string t=s.substr(st,pos-st);
            while(!t.empty()&&t.back()==' ')t.pop_back();
            return t;
        }
    }
};
static string innerArr(const string& s){ if(s.size()>=2 && s.front()=='[' && s.back()==']') return s.substr(1,s.size()-2); return s; }
static vector<string> splitTop(const string& s){
    vector<string> parts; int depth=0,start=0;
    for(int i=0;i<(int)s.size();i++){
        if(s[i]=='['||s[i]=='{')depth++;
        else if(s[i]==']'||s[i]=='}')depth--;
        else if(s[i]==','&&depth==0){parts.push_back(s.substr(start,i-start));start=i+1;}
    }
    if(start<(int)s.size()) parts.push_back(s.substr(start));
    return parts;
}
static vector<int> readIntVec(Tok& tok){
    string arr=tok.nextToken();
    if(arr=="[]"||arr.empty())return {};
    auto parts=splitTop(innerArr(arr)); vector<int> v;
    for(auto&p:parts) if(!p.empty()) v.push_back(stoi(p)); return v;
}
static vector<vector<int>> readInt2D(Tok& tok){
    string arr=tok.nextToken();
    if(arr=="[]"||arr.empty())return {};
    auto rows=splitTop(innerArr(arr)); vector<vector<int>> mat;
    for(auto&r:rows){Tok t2;t2.s="["+innerArr(r)+"]";t2.pos=0;mat.push_back(readIntVec(t2));} return mat;
}
static vector<string> readStrVec(Tok& tok){
    string arr=tok.nextToken();
    if(arr=="[]"||arr.empty())return {};
    auto parts=splitTop(innerArr(arr)); vector<string> v;
    for(auto&p:parts){string tmp=p;if(!tmp.empty()&&tmp.front()=='"')tmp=tmp.substr(1,tmp.size()-2);v.push_back(tmp);}return v;
}
static vector<char> readCharVec(Tok& tok){
    auto sv=readStrVec(tok); vector<char> v; for(auto&s:sv) if(!s.empty()) v.push_back(s[0]); return v;
}
static vector<vector<char>> readChar2D(Tok& tok){
    string arr=tok.nextToken();
    if(arr=="[]"||arr.empty())return {};
    auto rows=splitTop(innerArr(arr)); vector<vector<char>> mat;
    for(auto&r:rows){Tok t2;t2.s="["+innerArr(r)+"]";t2.pos=0;mat.push_back(readCharVec(t2));} return mat;
}
static int readInt(Tok& tok){ string t=tok.nextToken(); return t.empty()?0:stoi(t); }
static long long readLong(Tok& tok){ string t=tok.nextToken(); return t.empty()?0LL:stoll(t); }
static string readStr(Tok& tok){ string s=tok.nextToken(); if(!s.empty()&&s.front()=='"')s=s.substr(1,s.size()-2); return s; }
static bool readBool(Tok& tok){ return tok.nextToken()=="true"; }
static double readDouble(Tok& tok){ string t=tok.nextToken(); return t.empty()?0.0:stod(t); }

